class Resource extends Base {
 mount(){this._value??={name:'Fieldwork collection',visibility:'Private',description:'A collection of observations, objects and useful ideas.'};this.instanceId=uid();this.render(`<section class="scene panel"><header><span class="label">A PROJECT, IN A LITTLE MORE DETAIL</span><h2>The useful details.</h2><p class="hint">Make a change, consider it, and apply it when you’re ready.</p></header><article class="project"><div class="art" aria-hidden="true"><i></i><i></i><i></i></div><div class="project-body"><span class="label">COLLECTION / 001</span><h3></h3><p></p><span class="visibility"></span></div></article><button class="primary trigger" aria-haspopup="dialog">${escape(this.text('label','Edit project details'))} ↗</button></section><dialog aria-labelledby="${this.instanceId}"><form><header class="row between"><div><span class="label">PROJECT INSPECTOR</span><h3 id="${this.instanceId}">Make the details yours.</h3></div><button class="close" type="button" aria-label="Close project inspector">×</button></header><div class="fields"><label>Project name<input name="name" required minlength="2" maxlength="60" autocomplete="off"/></label><label>Visibility<select name="visibility"><option>Private</option><option>Shared</option><option>Public</option></select></label><label>Description<textarea name="description" rows="5" maxlength="250"></textarea></label><div class="info"><span>◈</span><p>Changes stay in the inspector until you apply them. Cancel keeps the previous version.</p></div></div><footer class="row between"><button type="button" class="secondary" data-cancel>Cancel</button><button type="submit" class="primary">Apply changes ↗</button></footer></form></dialog>`,`.scene{min-height:490px;padding:32px;background:var(--bg)}h2{font:400 clamp(27px,4vw,39px) Georgia;letter-spacing:-1px;margin:13px 0}.project{display:flex;border:1px solid var(--line);border-radius:12px;overflow:hidden;margin:27px 0 22px}.art{width:32%;min-width:100px;background:#71816a;position:relative;overflow:hidden}.art i{position:absolute;left:30%;top:25%;width:55px;height:90px;background:#c8cbb4;border-radius:50% 50% 0 0;transform:rotate(-12deg);box-shadow:12px 12px 0 #172b2422}.art i+i{left:48%;top:45%;opacity:.65}.art i+i+i{left:5%;top:60%;opacity:.2}.project-body{padding:24px;flex:1;min-width:0}.project h3{font:400 23px Georgia;margin:10px 0}.project p{font-size:11px;line-height:1.8;color:var(--muted)}.visibility{display:inline-block;color:var(--accent);font-size:8px;border:1px solid #aac2923a;border-radius:5px;padding:4px 7px;margin-top:15px}.trigger{font-size:11px}dialog{position:fixed;left:auto;right:0;top:0;bottom:0;margin:0;width:420px;height:100dvh;max-height:100dvh;max-width:calc(100vw - 18px);border-radius:18px 0 0 18px;border-right:0}form{height:100%;display:flex;flex-direction:column}dialog header{padding:25px 24px}dialog h3{font:400 24px Georgia;margin-top:12px}.fields{padding:26px 24px;flex:1;overflow:auto}.fields label{display:flex;flex-direction:column;gap:10px;font-size:11px;margin-bottom:25px}.fields input,.fields select,.fields textarea{width:100%;font-size:13px;resize:vertical}.info{display:flex;gap:10px;padding:17px;border:1px solid var(--line);background:var(--bg);border-radius:9px;color:var(--muted)}.info>span{font-size:23px;color:var(--accent)}.info p{font-size:11px;line-height:1.8}footer{padding:20px 24px;border-top:1px solid var(--line)}footer button{font-size:11px}@media(max-width:480px){.scene{padding:26px 20px}.project-body{padding:19px 17px}.project h3{font-size:20px}.art{min-width:80px}.fields{padding:23px 20px}}`);this.setupDialog(this.$('dialog'),this.$('.trigger'));this.listen(this.$('.trigger'),'click',()=>this.open());this.listen(this.$('.close'),'click',()=>this.close());this.listen(this.$('[data-cancel]'),'click',()=>this.close());this.listen(this.$('form'),'submit',e=>{e.preventDefault();if(!this.$('form').reportValidity())return;const form=new FormData(this.$('form'));this.value={name:String(form.get('name')).trim(),visibility:String(form.get('visibility')),description:String(form.get('description')).trim()};this.close();this.emit('details-change',this.value);});this.paint();}
 get value(){return{...this._value};}
 set value(value){this._value={name:String(value?.name||'Untitled project').slice(0,60),visibility:['Private','Shared','Public'].includes(value?.visibility)?value.visibility:'Private',description:String(value?.description||'').slice(0,250)};if(this._connected)this.paint();}
 paint(){this.$('.project h3').textContent=this._value.name;this.$('.project p').textContent=this._value.description;this.$('.visibility').textContent=this._value.visibility;}
 open(){const dialog=this.$('dialog');this.$('[name=name]').value=this._value.name;this.$('[name=visibility]').value=this._value.visibility;this.$('[name=description]').value=this._value.description;if(!dialog.open){this.dialogTrigger=this.$('.trigger');dialog.showModal();}this.$('[name=name]').focus();this.tween(dialog,[{transform:'translateX(100%)',opacity:.5},{transform:'translateX(0)',opacity:1}],{duration:400});}
 close(){this.$('dialog').close();}
 configured(name){if(name==='label')this.$('.trigger').textContent=this.text('label','Edit project details')+' ↗';}
 teardown(){this.$('dialog')?.close();}
}
